// Des: Read live feeds: SSE and long-poll by own GET, WebSocket by Chrome
// Flo: worker thread reads lines > SSE events or NDJSON lines become frames > main waits for frame cap or deadline > stop flag > JSONL out; WebSocket: Network events from the page's own socket
// I/O: URL + caps (caller) > frames (copies) and a JSONL text; errors BadStatus NoBrowser BrowFail
// ===================================================================
const std = @import("std"); const http = std.http; const mem = std.mem; const safe = @import("nt-safe-guar.zig"); const urln = @import("ut-urlz-norm.zig"); const rend = @import("nt-brow-rend.zig"); const cdp = @import("nt-brow-cdpz.zig");
const CF = .{ .lnez = 1 << 20, .evnt = "text/event-stream", .join = 1500, .tick = 10 };
pub const Opts = struct { time_mill: u32 = 30000, framz: u32 = 1000, priv: bool = false, uagt: []const u8 = "scra/0.1.0", repeat: bool = false };
const Shr = struct { gpaz: std.mem.Allocator, iozz: std.Io, urlz: []u8, opts: Opts, lock: std.atomic.Value(bool) = .init(false), frames: std.ArrayList([]u8) = .empty, done: std.atomic.Value(bool) = .init(false), stop: std.atomic.Value(bool) = .init(false), refs: std.atomic.Value(u32) = .init(2), code: std.atomic.Value(u16) = .init(0), sse: std.atomic.Value(bool) = .init(false),
fn lck(self: *Shr) void { while (self.lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {} }
fn unl(self: *Shr) void { self.lock.store(false, .release); }
fn full(self: *Shr) bool { self.lck(); defer self.unl(); return self.frames.items.len >= self.opts.framz; }
fn push(self: *Shr, txt: []const u8) void { const cp = self.gpaz.dupe(u8, txt) catch return; self.lck(); defer self.unl(); if (self.frames.items.len >= self.opts.framz) { self.gpaz.free(cp); return; } self.frames.append(self.gpaz, cp) catch self.gpaz.free(cp); }
fn rel(self: *Shr) void { if (self.refs.fetchSub(1, .acq_rel) == 1) { for (self.frames.items) |fr| self.gpaz.free(fr); self.frames.deinit(self.gpaz); const gpaz = self.gpaz; gpaz.free(self.urlz); gpaz.destroy(self); } } };
fn ctypOf(head: http.Client.Response.Head) []const u8 { var iter = head.iterateHeaders(); while (iter.next()) |item| { if (std.ascii.eqlIgnoreCase(item.name, "content-type")) return item.value; } return ""; }
fn once(shr: *Shr) !u32 { const gpaz = shr.gpaz; const part = try urln.urlSplit(shr.urlz); try safe.hostChek(shr.iozz, part.host, shr.opts.priv); const uri = std.Uri.parse(shr.urlz) catch return error.BadUrl; var clnt: http.Client = .{ .allocator = gpaz, .io = shr.iozz }; defer clnt.deinit(); var hdr = [_]http.Header{.{ .name = "Accept", .value = "text/event-stream, application/x-ndjson, application/json" }}; var req = try clnt.request(.GET, uri, .{ .redirect_behavior = .unhandled, .keep_alive = false, .headers = .{ .user_agent = .{ .override = shr.opts.uagt } }, .extra_headers = &hdr }); defer req.deinit(); req.accept_encoding = @splat(false); req.accept_encoding[@backingInt(http.ContentEncoding.identity)] = true; try req.sendBodiless(); var redb: [4096]u8 = undefined; var resp = try req.receiveHead(&redb); const code: u16 = @backingInt(resp.head.status); shr.code.store(code, .release); if (code < 200 or code >= 300) return error.BadStatus; const sse = std.ascii.findIgnoreCase(ctypOf(resp.head), CF.evnt) != null; shr.sse.store(sse, .release); const tbuf = try gpaz.alloc(u8, CF.lnez); defer gpaz.free(tbuf); const rdr = resp.reader(tbuf); var cur: std.ArrayList(u8) = .empty; defer cur.deinit(gpaz); var got: u32 = 0;
while (!shr.stop.load(.acquire) and !shr.full()) { const line = rdr.takeDelimiterInclusive('\n') catch break; const trm = mem.trimEnd(u8, line, "\r\n"); if (!sse) { if (trm.len > 0) { shr.push(trm); got += 1; } continue; } if (trm.len == 0) { if (cur.items.len > 0) { shr.push(cur.items); got += 1; cur.clearRetainingCapacity(); } continue; } if (trm[0] == ':') continue; if (mem.startsWith(u8, trm, "data:")) { var vl = trm[5..]; if (vl.len > 0 and vl[0] == ' ') vl = vl[1..]; if (cur.items.len > 0) cur.append(gpaz, '\n') catch {}; cur.appendSlice(gpaz, vl) catch {}; } } if (sse and cur.items.len > 0 and !shr.stop.load(.acquire)) { shr.push(cur.items); got += 1; } return got; }
fn work(shr: *Shr) void { while (!shr.stop.load(.acquire) and !shr.full()) { const got = once(shr) catch break; if (got == 0 or shr.sse.load(.acquire) or !shr.opts.repeat) break; } shr.done.store(true, .release); shr.rel(); }
pub fn sseRead(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, urlz: []const u8, opts: Opts) ![]const []const u8 { const shr = try gpaz.create(Shr); shr.* = .{ .gpaz = gpaz, .iozz = iozz, .urlz = try gpaz.dupe(u8, urlz), .opts = opts }; const thr = std.Thread.spawn(.{}, work, .{shr}) catch { shr.rel(); shr.rel(); return error.Unexpected; }; thr.detach(); const dead = cdp.nowMs(iozz) + opts.time_mill; while (!shr.done.load(.acquire) and !shr.full() and cdp.nowMs(iozz) < dead) std.Io.sleep(iozz, .fromMilliseconds(CF.tick), .awake) catch {}; shr.stop.store(true, .release); const jend = cdp.nowMs(iozz) + CF.join; while (!shr.done.load(.acquire) and cdp.nowMs(iozz) < jend) std.Io.sleep(iozz, .fromMilliseconds(CF.tick), .awake) catch {}; const code = shr.code.load(.acquire); var outp: std.ArrayList([]const u8) = .empty; shr.lck(); for (shr.frames.items) |fr| outp.append(aren, aren.dupe(u8, fr) catch continue) catch {}; shr.unl(); shr.rel(); if (outp.items.len == 0 and (code < 200 or code >= 300) and code != 0) return error.BadStatus; return outp.toOwnedSlice(aren); }
pub fn wsRead(rnd: *rend.Rndr, aren: std.mem.Allocator, urlz: []const u8, opts: Opts) ![]const []const u8 { if (!rnd.avail()) return error.NoBrowser; const pgz = rnd.pageGet() catch return error.NoBrowser; const conn = pgz.conn; var outp: std.ArrayList([]const u8) = .empty; _ = conn.callJson(aren, "Network.enable", "", 5000) catch { rnd.reset(); return error.BrowFail; }; _ = conn.callJson(aren, "Page.enable", "", 5000) catch { rnd.reset(); return error.BrowFail; }; var from: usize = conn.evCount(); const prm = try std.json.Stringify.valueAlloc(aren, .{ .url = urlz }, .{}); _ = conn.callJson(aren, "Page.navigate", prm, 10000) catch { rnd.reset(); return error.BrowFail; }; const dead = cdp.nowMs(rnd.iozz) + opts.time_mill; while (outp.items.len < opts.framz) { const left = dead - cdp.nowMs(rnd.iozz); if (left <= 0) break; const msg = (conn.evWait(aren, "Network.webSocketFrameReceived", &from, @intCast(left)) catch { rnd.reset(); return error.BrowFail; }) orelse break; const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, msg, .{}) catch continue; if (valu != .object) continue; const prms = valu.object.get("params") orelse continue; if (prms != .object) continue; const resp = prms.object.get("response") orelse continue; if (resp != .object) continue; const pay = resp.object.get("payloadData") orelse continue; if (pay == .string) try outp.append(aren, pay.string); } return outp.toOwnedSlice(aren); }
pub fn jsonl(aren: std.mem.Allocator, frames: []const []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; for (frames) |fr| { if (std.json.validate(aren, fr) catch false) { try outp.appendSlice(aren, fr); } else { try outp.appendSlice(aren, try std.json.Stringify.valueAlloc(aren, fr, .{})); } try outp.append(aren, '\n'); } return outp.toOwnedSlice(aren); }
